return function(ctx)
    local players = {}
    for _, player in ipairs(GameData.GetPlayers()) do players[#players + 1] = 'player:' .. string.gsub(player.playerId, '^p', '') end
    return { Effect.SelectInfluence({ player = ctx.playerId, operation = 'remove', subjectFilter = 'player', count = 1, requiredCount = 0, promptKey = 'effect.influence.choose' }), Effect.WithPresentation(Effect.Choice({ interactionType = 'effect.choice.execute', player = ctx.playerId, promptKey = 'infected.company.place_or_move', branches = { { id = 'place', effects = { Effect.PlaceInfluence({ executingPlayer = ctx.playerId, influenceSource = 'company_supply', ownerSubject = { kind = 'company', companyId = 'stonehoove_security' }, causeKind = 'other_intrinsic_flow' }) } }, { id = 'move', effects = { Effect.SelectInfluence({ player = ctx.playerId, operation = 'move', subjectFilter = 'any', excludedSubjectKeys = players, count = 2, requiredCount = 0, promptKey = 'infected.company.move' }) } } } }), { interaction = { prompt = Text.Ref('core:interaction.company.place_or_move'), options = { { candidateId = 'place', label = Text.Ref('core:interaction.company.place') }, { candidateId = 'move', label = Text.Ref('core:interaction.company.move_two') } } } }) }
end
